    "adminAmbassadors.subtitle": "Shqyrto aplikimet e ambasadorëve dhe menaxho statusin e programit.",
    "adminAmbassadors.tabApproved": "Miratuar",
    "adminAmbassadors.noApplicationsFound": "Nuk u gjet asnjë aplikim ambasadori.",
    "adminAmbassadors.countryLabel": "Vendi:",
    "adminAmbassadors.motivationLabel": "Motivimi:",
    "adminAmbassadors.audienceLabel": "Audienca:",
    "adminAmbassadors.confirmApprove": "Të miratohet ky aplikim ambasadori?",
    "adminAmbassadors.confirmRestore": "Të rikthehet statusi i këtij ambasadori?",
    "adminAmbassadors.promptSuspendReason": "Arsyeja e pezullimit të këtij ambasadori (opsionale):",
    "adminAmbassadors.errFailedLoad": "Ngarkimi i aplikimeve të ambasadorëve dështoi",
